/* ---------- About: "One mind. Multiple disciplines." ----------
   Layout and looping layers. Entrances and scroll effects live in About.tsx (GSAP).
   Elements that GSAP moves never carry a CSS transition or animation on the same property:
   the hover/loop styles sit on an inner element instead. */
.ab {
  position: relative;
  isolation: isolate;
  overflow-x: clip;
  padding-block: clamp(5rem, 12vw, 10rem) clamp(3.5rem, 7vw, 6rem);
}
/* ---------- backdrop ---------- */
.ab-grid {
  position: absolute;
  inset: 0;
  z-index: -2;
  pointer-events: none;
  background-image: radial-gradient(rgb(255 255 255 / 0.1) 1px, transparent 1.3px);
  background-size: 28px 28px;
  -webkit-mask-image: radial-gradient(55% 45% at 30% 42%, #000 0%, transparent 80%);
  mask-image: radial-gradient(55% 45% at 30% 42%, #000 0%, transparent 80%);
}
[dir='rtl'] .ab-grid {
  -webkit-mask-image: radial-gradient(55% 45% at 70% 42%, #000 0%, transparent 80%);
  mask-image: radial-gradient(55% 45% at 70% 42%, #000 0%, transparent 80%);
}
@media (max-width: 1023px) {
  .ab-grid,
  [dir='rtl'] .ab-grid {
    -webkit-mask-image: radial-gradient(70% 30% at 50% 38%, #000 0%, transparent 80%);
    mask-image: radial-gradient(70% 30% at 50% 38%, #000 0%, transparent 80%);
  }
}
/* Giant outlined word behind the heading. */
.ab-wm {
  position: absolute;
  z-index: -1;
  top: clamp(1.5rem, 5vw, 4rem);
  inset-inline-end: -3vw;
  font-size: clamp(8rem, 30vw, 30rem);
  line-height: 0.8;
  font-weight: 800;
  letter-spacing: -0.05em;
  color: transparent;
  -webkit-text-stroke: 1px rgb(255 255 255 / 0.07);
  white-space: nowrap;
  pointer-events: none;
  user-select: none;
}
/* ---------- layout ----------
   Phones: heading, portrait, lead, principles. Desktop: portrait on its own column. */
.ab-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: 'head' 'portrait' 'lead' 'principles';
  row-gap: 3.25rem;
}
.ab-head {
  grid-area: head;
  min-width: 0;
}
.ab-portrait {
  grid-area: portrait;
}
.ab-lead {
  grid-area: lead;
}
.ab-principles {
  grid-area: principles;
}
@media (min-width: 1024px) {
  .ab-layout {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.05fr);
    grid-template-areas: 'portrait head' 'portrait lead' 'portrait principles';
    grid-template-rows: auto auto 1fr;
    column-gap: clamp(3rem, 6vw, 7.5rem);
    row-gap: 0;
  }
  .ab-portrait {
    align-self: center;
  }
  .ab-lead {
    margin-top: 2.25rem;
  }
  .ab-principles {
    margin-top: 3rem;
    align-self: start;
  }
}
/* ---------- eyebrow + heading ---------- */
.ab-eb {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  margin-bottom: 1.6rem;
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.34em;
  text-transform: uppercase;
}
[dir='rtl'] .ab-eb {
  letter-spacing: 0;
}
.ab-eb-dot {
  display: block;
  width: 0.62rem;
  height: 0.62rem;
  flex-shrink: 0;
}
.ab-eb-line {
  display: block;
  width: 2.75rem;
  height: 1px;
  background: linear-gradient(90deg, var(--color-signal), rgb(255 255 255 / 0.55));
  transform-origin: left center;
}
[dir='rtl'] .ab-eb-line {
  background: linear-gradient(270deg, var(--color-signal), rgb(255 255 255 / 0.55));
  transform-origin: right center;
}
.ab-eb-text {
  display: block;
  padding-block: 0.15em;
}
.ab-title {
  font-size: clamp(2.15rem, 9.6vw, 3.75rem);
  line-height: 0.98;
  letter-spacing: -0.035em;
  font-weight: 800;
  text-transform: uppercase;
}
@media (min-width: 1024px) {
  .ab-title {
    font-size: clamp(2.75rem, 4.6vw, 5.4rem);
  }
}
[dir='rtl'] .ab-title {
  line-height: 1.32;
  letter-spacing: 0;
}
.ab-line {
  display: block;
}
/* Each word is its own mask, so letters rise out of their own word even when a line wraps. */
.ab-word {
  display: inline-block;
  overflow: hidden;
  vertical-align: top;
  padding: 0.1em 0.05em;
  margin: -0.1em -0.05em;
}
[dir='rtl'] .ab-word {
  padding-block: 0.28em;
  margin-block: -0.28em;
}
.ab-nowrap {
  white-space: nowrap;
}
.ab-ch {
  display: inline-block;
  transform-origin: 0 100%;
}
/* Outline that the second line fills in letter by letter (only when motion is on). */
.js-motion .ab-l2 .ab-ch {
  -webkit-text-stroke: 1px #fff;
}
.ab-dotp {
  display: inline-block;
  color: var(--color-signal);
  transform-origin: 50% 80%;
  text-shadow: 0 0 22px rgb(246 98 13 / 0.75);
}
/* ---------- lead ---------- */
.ab-lead {
  max-width: 44ch;
  font-size: clamp(1.125rem, 1.55vw, 1.375rem);
  font-weight: 600;
  line-height: 1.7;
  color: #fff;
}
[dir='rtl'] .ab-lead {
  line-height: 1.95;
}
/* ---------- portrait ---------- */
.ab-portrait {
  margin: 0;
  width: 100%;
  max-width: min(330px, 100% - 1.5rem);
  margin-inline: auto;
}
@media (min-width: 640px) {
  .ab-portrait {
    max-width: 380px;
  }
}
@media (min-width: 1024px) {
  /* Leaves room on both sides for the orbiting chips. */
  .ab-portrait {
    max-width: min(400px, 100% - 7.5rem);
  }
}
.ab-stage-wrap {
  perspective: 1100px;
}
.ab-stage {
  position: relative;
  transform-style: preserve-3d;
}
.ab-halo {
  position: absolute;
  inset: -20% -32%;
  z-index: -1;
  background: radial-gradient(closest-side, rgb(246 98 13 / 0.34), rgb(246 98 13 / 0.1) 50%, transparent 78%);
  pointer-events: none;
  animation: ab-breathe 6.5s ease-in-out infinite;
}
/* The A from the logo, drawn behind the card. */
.ab-aline {
  position: absolute;
  left: -14%;
  top: -11%;
  width: 128%;
  height: 120%;
  overflow: visible;
  pointer-events: none;
}
.ab-aline path {
  fill: none;
  stroke: var(--color-signal);
  stroke-width: 2;
  stroke-dasharray: 1;
}
.ab-card {
  position: relative;
  aspect-ratio: 3 / 4;
  overflow: hidden;
  border-radius: 2rem;
  container-type: inline-size;
  background: var(--color-navy-deep);
  box-shadow:
    0 50px 90px -40px rgb(0 0 0 / 0.7),
    0 0 0 1px rgb(255 255 255 / 0.08);
}
.ab-par {
  position: absolute;
  inset: 0;
}
/* The picture at its own proportions (not object-fit), so the eyelids and the visor glow
   can be placed in picture coordinates and follow it through every zoom and parallax.
   top: -7.33% shows the same crop as object-position 50% 22% did. */
.ab-imgbox {
  position: absolute;
  left: 0;
  top: -7.33%;
  width: 100%;
  aspect-ratio: 720 / 1280;
  transform: scale(1.06);
  transform-origin: 43% 28%;
}
.ab-img {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}
/* Eyelids: visor-orange patches over the two eyes (picture px: L 216-236 x 343-422, R 341-382 x 327-409). */
.ab-lid {
  position: absolute;
  border-radius: 50%;
  transform: scaleY(0);
  transform-origin: 50% 0;
  filter: blur(0.6px);
  animation: ab-blink 5.2s ease-in-out infinite;
}
.ab-lid-l {
  left: 29.8%;
  top: 26.7%;
  width: 3.2%;
  height: 6.4%;
  background: linear-gradient(90deg, #fea51d, #fb7708);
}
.ab-lid-r {
  left: 47.2%;
  top: 25.4%;
  width: 6%;
  height: 6.7%;
  background: linear-gradient(90deg, #f26707, #fb940a);
}
.ab-visor {
  position: absolute;
  left: 43%;
  top: 28%;
  width: 72%;
  aspect-ratio: 1;
  translate: -50% -50%;
  pointer-events: none;
}
.ab-visor-i {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: radial-gradient(closest-side, rgb(255 178 92 / 0.55), rgb(246 98 13 / 0.18) 55%, transparent 100%);
  mix-blend-mode: screen;
  animation: ab-visor 4.6s ease-in-out infinite;
}
.ab-scan {
  position: absolute;
  inset-inline: 0;
  top: 0;
  height: 22%;
  opacity: 0;
  background: linear-gradient(180deg, transparent, rgb(246 98 13 / 0.12) 70%, rgb(255 176 122 / 0.55) 97%, #ffd2b0 100%);
  mix-blend-mode: screen;
  pointer-events: none;
}
.ab-shade {
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgb(3 14 46 / 0.92) 0%, rgb(3 14 46 / 0.35) 26%, transparent 46%);
  pointer-events: none;
}
/* HUD on the card */
.ab-hud-top {
  position: absolute;
  top: 1rem;
  inset-inline-start: 1rem;
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.42rem 0.75rem 0.42rem 0.6rem;
  border-radius: 999px;
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.28em;
  background: rgb(3 14 46 / 0.6);
  border: 1px solid rgb(255 255 255 / 0.14);
}
.ab-live {
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-signal);
  box-shadow: 0 0 10px var(--color-signal);
  animation: ab-live 1.7s ease-in-out infinite;
}
.ab-hud {
  position: absolute;
  inset-inline: 1.15rem;
  bottom: 1.05rem;
  display: flex;
  align-items: flex-end;
  gap: 0.9rem;
}
.ab-stat {
  display: flex;
  flex-direction: column;
}
.ab-stat-end {
  align-items: flex-end;
  text-align: end;
}
.ab-stat-n {
  font-size: clamp(1.6rem, 12cqw, 2.6rem);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
}
.ab-stat-end .ab-stat-n {
  color: var(--color-signal);
  text-shadow: 0 0 18px rgb(246 98 13 / 0.6);
}
.ab-stat-l {
  margin-top: 0.4rem;
  font-size: clamp(0.56rem, 3cqw, 0.7rem);
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgb(255 255 255 / 0.82);
}
[dir='rtl'] .ab-stat-l {
  font-size: clamp(0.72rem, 3.6cqw, 0.85rem);
  letter-spacing: 0;
}
/* 01 → 07: a line with a signal running along it. */
.ab-hud-link {
  position: relative;
  flex: 1;
  height: 1px;
  margin-bottom: 1.05rem;
  background: linear-gradient(90deg, rgb(255 255 255 / 0.6), var(--color-signal));
  transform-origin: left center;
}
[dir='rtl'] .ab-hud-link {
  background: linear-gradient(270deg, rgb(255 255 255 / 0.6), var(--color-signal));
  transform-origin: right center;
}
.ab-hud-link::after {
  content: '';
  position: absolute;
  top: -2.5px;
  left: 0;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 10px var(--color-signal), 0 0 4px #fff;
  animation: ab-run 2.6s cubic-bezier(0.65, 0, 0.35, 1) infinite;
}
[dir='rtl'] .ab-hud-link::after {
  animation-name: ab-run-rtl;
}
/* Viewfinder corners */
.ab-corner {
  position: absolute;
  width: 22px;
  height: 22px;
  border: 0 solid var(--color-signal);
  pointer-events: none;
}
.ab-c-tl {
  top: -12px;
  left: -12px;
  border-top-width: 2px;
  border-left-width: 2px;
  border-top-left-radius: 8px;
  transform-origin: 0 0;
}
.ab-c-tr {
  top: -12px;
  right: -12px;
  border-top-width: 2px;
  border-right-width: 2px;
  border-top-right-radius: 8px;
  transform-origin: 100% 0;
}
.ab-c-bl {
  bottom: -12px;
  left: -12px;
  border-bottom-width: 2px;
  border-left-width: 2px;
  border-bottom-left-radius: 8px;
  transform-origin: 0 100%;
}
.ab-c-br {
  bottom: -12px;
  right: -12px;
  border-bottom-width: 2px;
  border-right-width: 2px;
  border-bottom-right-radius: 8px;
  transform-origin: 100% 100%;
}
/* Orbit: visible and animated at every screen size. */
.ab-orbit {
  display: block;
  position: absolute;
  inset: 0;
  pointer-events: none;
  transform-style: preserve-3d;
}
.ab-links {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}
.ab-link {
  fill: none;
  stroke: rgb(255 255 255 / 0.32);
  stroke-width: 1;
  stroke-dasharray: 1;
}
.ab-pulse {
  fill: none;
  stroke: var(--color-signal);
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-dasharray: 0.07 0.93;
  filter: drop-shadow(0 0 3px rgb(246 98 13 / 0.9));
  animation: ab-pulse 3.4s linear infinite;
}
.ab-node {
  fill: var(--color-signal);
}
.ab-chip {
  position: absolute;
  left: var(--x);
  top: var(--y);
  translate: -50% -50%;
}
.ab-chip-i {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
  padding: 0.5rem 0.9rem 0.5rem 0.62rem;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  background: rgb(5 23 70 / 0.9);
  border: 1px solid rgb(255 255 255 / 0.16);
  box-shadow: 0 14px 30px -12px rgb(0 0 0 / 0.6);
  animation: ab-float 5.5s ease-in-out infinite;
  animation-delay: var(--d);
}
[dir='rtl'] .ab-chip-i {
  padding: 0.45rem 0.62rem 0.5rem 0.9rem;
  letter-spacing: 0;
}
.ab-chip-dot {
  display: block;
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: var(--color-signal);
  box-shadow: 0 0 10px var(--color-signal);
}
.ab-cap {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  max-width: 34ch;
  margin-top: 2.1rem;
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.65;
  color: rgb(255 255 255 / 0.92);
}
.ab-cap-dot {
  margin-top: 0.5rem;
  width: 0.6rem;
  height: 0.6rem;
}
/* Mobile labels use the matching MOBILE_ORBIT signal paths in About.tsx. */
@media (max-width: 1023px) {
  .ab-portrait {
    max-width: min(330px, calc(100% - 3rem));
  }
  .ab-orbit { z-index: 3; }
  .ab-chip { max-width: 42%; }
  .ab-chip-i,
  [dir='rtl'] .ab-chip-i {
    justify-content: center;
    gap: .3rem;
    padding: .4rem .5rem;
    white-space: normal;
    text-align: center;
    overflow-wrap: anywhere;
    font-size: clamp(.58rem, 2.5vw, .72rem);
    line-height: 1.45;
    letter-spacing: 0;
  }
  .ab-chip-dot {
    flex-shrink: 0;
    width: .3rem;
    height: .3rem;
  }
  .ab-card { border-radius: 1.5rem; }
  .ab-cap { margin-top: 1.75rem; }
}
/* ---------- principles ---------- */
.ab-principles {
  display: grid;
  gap: 1rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
@media (min-width: 640px) {
  .ab-principles {
    grid-template-columns: 1fr 1fr;
  }
}
.ab-pr-cell {
  display: flex;
}
.ab-pr {
  position: relative;
  flex: 1;
  overflow: hidden;
  padding: 1.5rem 1.4rem 1.65rem;
  border-radius: 1.25rem;
  background: rgb(255 255 255 / 0.035);
  border: 1px solid rgb(255 255 255 / 0.1);
  transition:
    transform 0.6s var(--ease-cine),
    border-color 0.5s,
    background-color 0.5s;
}
/* Spotlight that follows the pointer (--mx/--my set from About.tsx). */
.ab-pr::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(260px circle at var(--mx, 50%) var(--my, 0%), rgb(246 98 13 / 0.2), transparent 70%);
  opacity: 0;
  transition: opacity 0.4s;
  pointer-events: none;
}
.ab-pr-rule {
  position: absolute;
  top: 0;
  inset-inline: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--color-signal), rgb(246 98 13 / 0));
  transform-origin: left center;
}
[dir='rtl'] .ab-pr-rule {
  background: linear-gradient(270deg, var(--color-signal), rgb(246 98 13 / 0));
  transform-origin: right center;
}
.ab-pr-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.1rem;
}
.ab-mask {
  display: block;
  overflow: hidden;
  padding-block: 0.08em;
  margin-block: -0.08em;
}
[dir='rtl'] .ab-mask {
  padding-block: 0.22em;
  margin-block: -0.22em;
}
.ab-pr-num {
  display: block;
  font-size: 2.5rem;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.03em;
  color: transparent;
  -webkit-text-stroke: 1px rgb(255 255 255 / 0.55);
}
.ab-pr-num-i {
  display: block;
  transition:
    color 0.5s,
    -webkit-text-stroke-color 0.5s;
}
.ab-pr-dot {
  display: block;
}
.ab-pr-dot-i {
  display: block;
  width: 0.55rem;
  height: 0.55rem;
  transition: transform 0.6s var(--ease-cine);
}
.ab-pr-t {
  display: block;
  font-size: clamp(1.25rem, 1.5vw, 1.4rem);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.01em;
}
[dir='rtl'] .ab-pr-t {
  letter-spacing: 0;
  line-height: 1.5;
}
.ab-pr-d {
  margin-top: 0.6rem;
  font-size: 1.0625rem;
  font-weight: 600;
  line-height: 1.6;
  color: rgb(255 255 255 / 0.84);
}
[dir='rtl'] .ab-pr-d {
  line-height: 1.85;
}
@media (hover: hover) {
  .ab-pr:hover {
    transform: translateY(-4px);
    border-color: rgb(246 98 13 / 0.55);
    background-color: rgb(255 255 255 / 0.05);
  }
  .ab-pr:hover::before {
    opacity: 1;
  }
  .ab-pr:hover .ab-pr-num-i {
    color: var(--color-signal);
    -webkit-text-stroke-color: var(--color-signal);
  }
  .ab-pr:hover .ab-pr-dot-i {
    transform: scale(1.9);
  }
}
/* ---------- crossing bands ---------- */
.ab-bands {
  position: relative;
  margin-top: clamp(3rem, 6vw, 5rem);
  padding-block: clamp(2.5rem, 5.5vw, 5rem);
}
.ab-band {
  position: relative;
  width: 124%;
  margin-left: -12%;
  overflow: hidden;
}
.ab-band-a {
  z-index: 2;
  background: var(--color-signal);
  color: var(--color-navy);
  box-shadow: 0 24px 60px -24px rgb(246 98 13 / 0.55);
  transform: rotate(-3deg);
}
.ab-band-b {
  position: absolute;
  z-index: 1;
  left: 0;
  top: 50%;
  translate: 0 -50%;
  background: #0d2a74;
  color: #fff;
  border-block: 1px solid rgb(255 255 255 / 0.14);
  box-shadow: 0 0 60px -10px rgb(0 0 0 / 0.5);
  transform: rotate(4deg);
}
.ab-mq {
  display: flex;
  width: max-content;
  animation: ab-mq 42s linear infinite;
}
.ab-band-b .ab-mq {
  animation-duration: 52s;
  animation-direction: reverse;
}
.ab-mq-group {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}
.ab-mq-word {
  padding-block: 0.5em;
  font-size: clamp(1.45rem, 4vw, 3.5rem);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  white-space: nowrap;
}
[dir='rtl'] .ab-mq-word {
  letter-spacing: 0;
  line-height: 1.35;
  padding-block: 0.35em;
}
.ab-band-a .ab-mq-word:nth-child(4n + 3) {
  color: transparent;
  -webkit-text-stroke: 1.5px var(--color-navy);
}
.ab-band-b .ab-mq-word {
  color: transparent;
  -webkit-text-stroke: 1.2px rgb(255 255 255 / 0.8);
}
.ab-band-b .ab-mq-word:nth-child(4n + 3) {
  color: #fff;
  -webkit-text-stroke: 0;
}
.ab-mq-sep {
  display: block;
  flex-shrink: 0;
  width: clamp(0.85rem, 1.8vw, 1.5rem);
  height: clamp(0.85rem, 1.8vw, 1.5rem);
  margin-inline: clamp(1rem, 2.6vw, 2.25rem);
}
.ab-band-a .ab-mq-sep {
  color: var(--color-navy);
}
.ab-band-b .ab-mq-sep {
  color: var(--color-signal);
}
/* ---------- loops ---------- */
@keyframes ab-breathe {
  0%,
  100% {
    opacity: 0.75;
    transform: scale(0.96);
  }
  50% {
    opacity: 1;
    transform: scale(1.04);
  }
}
@keyframes ab-visor {
  0%,
  100% {
    opacity: 0.45;
    transform: scale(0.94);
  }
  50% {
    opacity: 0.95;
    transform: scale(1.05);
  }
}
@keyframes ab-blink {
  0%,
  86%,
  91%,
  94%,
  100% {
    transform: scaleY(0);
  }
  88.5%,
  92.5% {
    transform: scaleY(1);
  }
}
@keyframes ab-live {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.25;
  }
}
@keyframes ab-run {
  0% {
    left: 0;
    opacity: 0;
  }
  15% {
    opacity: 1;
  }
  85% {
    opacity: 1;
  }
  100% {
    left: calc(100% - 6px);
    opacity: 0;
  }
}
@keyframes ab-run-rtl {
  0% {
    left: calc(100% - 6px);
    opacity: 0;
  }
  15% {
    opacity: 1;
  }
  85% {
    opacity: 1;
  }
  100% {
    left: 0;
    opacity: 0;
  }
}
@keyframes ab-pulse {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}
@keyframes ab-float {
  0%,
  100% {
    transform: translateY(-5px);
  }
  50% {
    transform: translateY(5px);
  }
}
@keyframes ab-mq {
  to {
    transform: translateX(-50%);
  }
}
/* Off screen: every loop holds still. */
.ab[data-off] *,
.ab[data-off] *::before,
.ab[data-off] *::after {
  animation-play-state: paused !important;
}
@media (prefers-reduced-motion: reduce) {
  .ab *,
  .ab *::before,
  .ab *::after {
    animation: none !important;
  }
  .ab-visor-i {
    opacity: 0.7;
  }
}
